class Completed {

    private int remaining;
    private int answer;

    public int kthSmallest(TreeNode root, int k) {

        remaining = k;
        answer = 0;
        inOrder(root);
        return answer;
    }

    private void inOrder(TreeNode node) {

        if (node == null || remaining == 0) {
            return;
        }

        inOrder(node.left);

        if (remaining == 0) {
            return;
        }

        remaining--;
        if (remaining == 0) {
            answer = node.val;
            return;
        }

        inOrder(node.right);
    }
}

